    var player = Minecraft.getInstance().player;
    if (player == null)
        return;

    var livingEntity = event.getEntity();
    if (livingEntity.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY) && livingEntity.isInvisibleTo(player)) {
        event.setCanceled(true);
    }
}

